function fail(code, detail = "") {
  throw new Error(detail ? `${code}:${detail}` : code);
}

function object(value) {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function clone(value) {
  return structuredClone(value);
}

function freezeDeep(value) {
  if (!value || typeof value !== "object" || Object.isFrozen(value)) return value;
  for (const child of Object.values(value)) freezeDeep(child);
  return Object.freeze(value);
}

function activeOnTablePiece(piece) {
  return piece?.isOnField === true
    && piece?.isDestroyed !== true
    && Number(piece?.currentModels || 0) > 0;
}

function sidePassed(state, sideKey, phase) {
  return state?.players?.[sideKey]?.passedPhases?.[phase] === true;
}

function phaseActivated(piece, phase) {
  return piece?.activatedPhases?.[phase] === true;
}

function hasOfficialPhaseActivationPrerequisite(sideKey, state, phase) {
  if (sidePassed(state, sideKey, phase)) return false;
  const onTableActivation = (state.pieces || []).some((piece) => (
    piece.sideKey === sideKey
      && activeOnTablePiece(piece)
      && !phaseActivated(piece, phase)
  ));
  if (onTableActivation || phase !== "movement") return onTableActivation;
  // A live unactivated reserve keeps Pass optional whenever deployment may still
  // exist in the current partial catalogue. Exact deploy legality is enumerated
  // separately by the reserve-deploy executor when that slice is enabled.
  return (state.pieces || []).some((piece) => (
    piece.sideKey === sideKey
      && piece?.isOnField !== true
      && piece?.isDestroyed !== true
      && Number(piece?.currentModels || 0) > 0
      && !phaseActivated(piece, phase)
  ));
}

function sortedManifest(manifest) {
  return clone(manifest).sort((left, right) => left.executorId.localeCompare(right.executorId));
}

function verifyCatalogue(catalogue) {
  const audit = verifyRuleAtomCatalogue(catalogue);
  const knownExecutors = new Map(KNOWN_EXECUTOR_MANIFEST.map((entry) => [entry.executorId, entry]));
  for (const executor of catalogue.executorManifest) {
    const known = knownExecutors.get(executor.executorId);
    if (!known || !isDeepStrictEqual(executor, known)) {
      fail("official_runtime_executor_manifest_mismatch", executor.executorId);
    }
  }
  const dependencySet = {
    rulesVersion: catalogue.rulesVersion,
    sourceSnapshotHashes: Object.fromEntries(catalogue.sourceSnapshots.map((snapshot) => [
      snapshot.sourceSnapshotId,
      snapshot.contentHash,
    ])),
    executorVersions: Object.fromEntries(catalogue.executorManifest.map((executor) => [
      executor.executorId,
      executor.executorVersion,
    ])),
  };
  const resolved = resolveExecutableRuleAtoms(catalogue, dependencySet);
  const observedIds = [...resolved.atomIds].sort((left, right) => left.localeCompare(right));
  const executableAtoms = catalogue.atoms.filter((atom) => atom.disposition === "executable");
  for (const atom of executableAtoms) {
    const allowedAtomIds = EXECUTOR_ATOM_IDS.get(atom.effect.executorId) || [];
    if (!allowedAtomIds.includes(atom.atomId)) {
      fail("official_runtime_atom_executor_assignment_mismatch", atom.atomId);
    }
  }
  const expectedIds = executableAtoms.map((atom) => atom.atomId)
    .sort((left, right) => left.localeCompare(right));
  if (!isDeepStrictEqual(observedIds, expectedIds)
    || observedIds.some((atomId) => !KNOWN_EXECUTABLE_ATOM_IDS.includes(atomId))) {
    fail("official_runtime_executable_atom_set_mismatch");
  }
  return { audit, resolved };
}

function withPassSettlementLineage(candidate, state, phase, passAtomIds) {
  const otherSideKey = candidate.sideKey === "player1" ? "player2" : "player1";
  if (!sidePassed(state, otherSideKey, phase)) return candidate;
  return {
    ...candidate,
    ruleAtomIds: [...new Set([
      ...(candidate.ruleAtomIds || []),
      ...passAtomIds,
    ])].sort((left, right) => left.localeCompare(right)),
    details: {
      ...(candidate.details || {}),
      phaseSettlementLineageIncluded: true,
    },
  };
}

function assertActionLineage(action, expectedIds) {
  const observedIds = [...(action.ruleAtomIds || [])].sort((left, right) => left.localeCompare(right));
  const expected = [...expectedIds].sort((left, right) => left.localeCompare(right));
  if (!isDeepStrictEqual(observedIds, expected)) fail("RULE_RUNTIME_ACTION_LINEAGE_MISMATCH");
  if (observedIds.some((atomId) => !KNOWN_EXECUTABLE_ATOM_IDS.includes(atomId))) {
    fail("RULE_RUNTIME_ACTION_ATOM_NOT_EXECUTABLE");
  }
}

function expectedHoldLineage(state, action, phase, holdAtomIds, passAtomIds) {
  const otherSideKey = action.sideKey === "player1" ? "player2" : "player1";
  if (!sidePassed(state, otherSideKey, phase)) return holdAtomIds;
  return [...new Set([
    ...holdAtomIds,
    ...passAtomIds,
  ])];
}

function stateSummary(state) {
  return {
    round: Number(state.round || 1),
    phase: String(state.phase || ""),
    activeSideKey: String(state.activeSideKey || ""),
    firstPlayerSideKey: String(state.firstPlayerSideKey || ""),
    pendingRangedAttackSequenceHash:
      state.pendingRangedAttackSequence?.pendingHash || null,
    pendingRangedAttackPieceId:
      state.pendingRangedAttackSequence?.pieceId || null,
    remainingBatchProfileKeys: [
      ...(state.pendingRangedAttackSequence?.remainingBatchProfileKeys || []),
    ],
    selectedBatchProfileKeys: [
      ...(state.pendingRangedAttackSequence?.originalBatchProfileKeys || []),
    ],
    sidearmUseMode: state.pendingRangedAttackSequence?.sidearmUseMode || null,
    latestActiveAbilityUseHash:
      (Array.isArray(state.activeAbilityUseHistory)
        ? state.activeAbilityUseHistory.at(-1)?.abilityUseHash
        : null) || null,
    pendingAbilityHash: state.pendingAbility?.pendingAbilityHash || null,
    pendingAbilityId: state.pendingAbility?.abilityId || null,
    pendingAbilityStage: state.pendingAbility?.stage || null,
    pendingRestorationReactionHash:
      state.pendingRestorationReaction?.pendingReactionHash || null,
    pendingRestorationSourcePieceId:
      state.pendingRestorationReaction?.sourcePieceId || null,
    pendingLifeSupportReactionHash:
      state.pendingLifeSupportReaction?.pendingReactionHash || null,
    pendingLifeSupportTargetPieceId:
      state.pendingLifeSupportReaction?.targetPieceId || null,
    pendingLifeSupportSourcePieceIds: [
      ...(state.pendingLifeSupportReaction?.eligibleSources || []).map((row) => (
        row.sourcePieceId
      )),
    ],
    pendingStimpackPrecisionHash:
      state.pendingAction?.schema === OFFICIAL_STIMPACK_PRECISION_PENDING_SCHEMA
        ? state.pendingAction.pendingHash
        : null,
    pendingStimpackPrecisionAttackerPieceId:
      state.pendingAction?.schema === OFFICIAL_STIMPACK_PRECISION_PENDING_SCHEMA
        ? state.pendingAction.attackerPieceId
        : null,
    pendingStimpackPrecisionSelectionCount:
      state.pendingAction?.schema === OFFICIAL_STIMPACK_PRECISION_PENDING_SCHEMA
        ? state.pendingAction.precisionSelections?.length || 0
        : 0,
    pendingStimpackCloseCombatPrecisionHash:
      state.pendingAction?.schema === OFFICIAL_STIMPACK_CLOSE_COMBAT_PENDING_SCHEMA
        ? state.pendingAction.pendingHash
        : null,
    pendingStimpackCloseCombatPrecisionAttackerPieceId:
      state.pendingAction?.schema === OFFICIAL_STIMPACK_CLOSE_COMBAT_PENDING_SCHEMA
        ? state.pendingAction.attackerPieceId
        : null,
    pendingStimpackCloseCombatPrecisionSelectionCount:
      state.pendingAction?.schema === OFFICIAL_STIMPACK_CLOSE_COMBAT_PENDING_SCHEMA
        ? state.pendingAction.precisionSelections?.length || 0
        : 0,
    pendingMarineMultiModelCloseCombatPrecisionHash:
      state.pendingAction?.schema
        === OFFICIAL_MARINE_MULTI_MODEL_STIMPACK_CLOSE_COMBAT_PENDING_SCHEMA
        ? state.pendingAction.pendingHash
        : null,
    pendingMarineMultiModelCloseCombatPrecisionAttackerPieceId:
      state.pendingAction?.schema
        === OFFICIAL_MARINE_MULTI_MODEL_STIMPACK_CLOSE_COMBAT_PENDING_SCHEMA
        ? state.pendingAction.attackerPieceId
        : null,
    pendingMarineMultiModelCloseCombatPrecisionSelectionCount:
      state.pendingAction?.schema
        === OFFICIAL_MARINE_MULTI_MODEL_STIMPACK_CLOSE_COMBAT_PENDING_SCHEMA
        ? state.pendingAction.precisionSelections?.length || 0
        : 0,
    ...(state.pendingAction?.schema
      === OFFICIAL_MARINE_MULTI_MODEL_CASUALTY_PRECISION_PENDING_SCHEMA
      ? {
          pendingMarineMultiModelCasualtyPrecisionHash:
            state.pendingAction.pendingHash,
          pendingMarineMultiModelCasualtyPrecisionAttackerPieceId:
            state.pendingAction.attackerPieceId,
          pendingMarineMultiModelCasualtyPrecisionSelectionCount:
            state.pendingAction.precisionSelections?.length || 0,
        }
      : {}),
    ...(state.pendingAction?.schema === OFFICIAL_MARINE_MULTI_MODEL_CASUALTY_PENDING_SCHEMA
      ? {
          pendingMarineMultiModelCasualtyHash: state.pendingAction.pendingHash,
          pendingMarineMultiModelCasualtyTargetPieceId:
            state.pendingAction.targetPieceId,
          pendingMarineMultiModelCasualtySelectionCount:
            state.pendingAction.casualtyDomain?.legalSelections?.length || 0,
        }
      : {}),
    ...(state.pendingAction?.schema === OFFICIAL_MARINE_MULTI_ENEMY_CASUALTY_PENDING_SCHEMA
      ? {
          pendingMarineMultiEnemyCasualtyHash: state.pendingAction.pendingHash,
          pendingMarineMultiEnemyCasualtyTargetPieceId:
            state.pendingAction.targetPieceId,
          pendingMarineMultiEnemyCasualtyCoEngagerPieceId:
            state.pendingAction.coEngagerPieceId,
          pendingMarineMultiEnemyCasualtySelectionCount:
            state.pendingAction.casualtyDomain?.legalSelections?.length || 0,
        }
      : {}),
    ...(state.pendingAction?.schema
      === OFFICIAL_MARINE_MULTI_ENEMY_STIMPACK_PRECISION_PENDING_SCHEMA
      ? {
          pendingMarineMultiEnemyStimpackPrecisionHash:
            state.pendingAction.pendingHash,
          pendingMarineMultiEnemyStimpackPrecisionAttackerPieceId:
            state.pendingAction.attackerPieceId,
          pendingMarineMultiEnemyStimpackPrecisionCoEngagerPieceId:
            state.pendingAction.coEngagerPieceId,
          pendingMarineMultiEnemyStimpackPrecisionSelectionCount:
            state.pendingAction.precisionSelections?.length || 0,
        }
      : {}),
    ...(state.pendingAction?.schema
      === OFFICIAL_MARINE_MULTI_ENEMY_STIMPACK_CASUALTY_PENDING_SCHEMA
      ? {
          pendingMarineMultiEnemyStimpackCasualtyHash:
            state.pendingAction.pendingHash,
          pendingMarineMultiEnemyStimpackCasualtyTargetPieceId:
            state.pendingAction.targetPieceId,
          pendingMarineMultiEnemyStimpackCasualtyCoEngagerPieceId:
            state.pendingAction.coEngagerPieceId,
          pendingMarineMultiEnemyStimpackCasualtySelectionCount:
            state.pendingAction.casualtyDomain?.legalSelections?.length || 0,
        }
      : {}),
    ...(state.pendingAction?.schema === OFFICIAL_MARINE_CHARGE_PENDING_SCHEMA
      ? {
          pendingMarineChargeHash: state.pendingAction.pendingHash,
          pendingMarineChargePieceId: state.pendingAction.pieceId,
          pendingMarineChargeRoll: state.pendingAction.roll,
          pendingMarineChargeDistanceInches:
            state.pendingAction.chargeRollDistanceInches,
        }
      : {}),
    ...(state.pendingAction?.schema === OFFICIAL_MARINE_CHARGE_V2_PENDING_SCHEMA
      ? {
          pendingMarineChargeV2Hash: state.pendingAction.pendingHash,
          pendingMarineChargeV2PieceId: state.pendingAction.pieceId,
          pendingMarineChargeV2Roll: state.pendingAction.roll,
          pendingMarineChargeV2DistanceInches:
            state.pendingAction.chargeRollDistanceInches,
          pendingMarineChargeV2SourceLockHash: state.pendingAction.sourceLockHash,
        }
      : {}),
  };
}

